form=function(type){if(type!=='checkout')return baseCheckoutForm(type);const p=accountProfile;const profile=p?`<section class="checkout-profile"><div><b>${escapeHtml(`${p.first_name||''} ${p.last_name||''}`.trim())}</b><span>${escapeHtml(p.address||'Adresse à confirmer')} · ${escapeHtml(p.phone||'Téléphone à confirmer')}</span></div><button type="button" onclick="toggleCheckoutProfile()">Modifier</button></section>`:'';const values={first:p?.first_name||'',last:p?.last_name||'',address:p?.address||'',phone:p?.phone||''};return `<main class="shell inner"><div class="form-wrap"><div class="crumb">Accueil / Livraison & paiement</div><div class="form-card"><h2>Livraison & paiement</h2>${profile}<form onsubmit="checkout(event)"><div class="field"><label>MODE DE LIVRAISON</label><select id="delivery"><option value="home">Livraison à domicile — 2 000 FCFA</option><option value="pickup">Retrait gratuit — OKOUMÉ</option></select></div><p class="status">Livraison à domicile : 2 000 FCFA · Retrait en boutique : gratuit</p><div id="checkout-profile-edit" class="${p?'is-collapsed':''}"><div class="two-fields"><div class="field"><label>PRÉNOM</label><input id="firstName" required value="${escapeHtml(values.first)}" placeholder="Votre prénom"></div><div class="field"><label>NOM</label><input id="lastName" required value="${escapeHtml(values.last)}" placeholder="Votre nom"></div></div><div class="field"><label>ADRESSE DE LIVRAISON</label><input id="address" required value="${escapeHtml(values.address)}" placeholder="Quartier, rue, repère"></div><div class="field"><label>TÉLÉPHONE</label><input id="phone" required value="${escapeHtml(values.phone)}" placeholder="077 63 88 64"></div></div><div class="field"><label>PAIEMENT</label><select id="paymentMethod"><option value="cod">Paiement à la livraison</option><option value="airtel_money">Airtel Money — 077 638 864</option></select></div><button class="btn" type="submit">Confirmer la commande&nbsp; →</button></form></div></div></main>`};
